# Expected values are SymPy's outputs for the same calls (roots).

skip_on_cran()

x <- Symbol("x"); a <- Symbol("a"); b <- Symbol("b"); c <- Symbol("c"); k <- Symbol("k", real = TRUE)
mi_fmt <- function(v) {
  if (!is.null(attr(v, "multiplicity"))) return(paste0("{", paste(vapply(seq_along(v), function(i) paste0(sstr(v[[i]]), ": ", attr(v, "multiplicity")[i]), ""), collapse = ", "), "}"))
  if (is.list(v)) return(paste0("[", paste(vapply(v, sstr, ""), collapse = ", "), "]"))
  sstr(v)
}

test_that("roots match SymPy", {
  expect_equal(mi_fmt(roots(x^2 - 3*x + 2, x)), "{2: 1, 1: 1}")
  expect_equal(mi_fmt(roots(x^3 - 1, x)), "{1: 1, -1/2 - sqrt(3)*I/2: 1, -1/2 + sqrt(3)*I/2: 1}")
  expect_equal(mi_fmt(roots((x - 1)^2*(x + 3), x)), "{-3: 1, 1: 2}")
  expect_equal(mi_fmt(roots(x^2 + 1, x)), "{-I: 1, I: 1}")
  expect_equal(mi_fmt(roots(x^4 - 1, x)), "{-1: 1, 1: 1, -I: 1, I: 1}")
  expect_equal(mi_fmt(roots(x^4 + 1, x)), "{-sqrt(2)/2 - sqrt(2)*I/2: 1, -sqrt(2)/2 + sqrt(2)*I/2: 1, sqrt(2)/2 - sqrt(2)*I/2: 1, sqrt(2)/2 + sqrt(2)*I/2: 1}")
  expect_equal(mi_fmt(roots(x^6 + 1, x)), "{-sqrt(3)/2 - I/2: 1, -sqrt(3)/2 + I/2: 1, -I: 1, I: 1, sqrt(3)/2 - I/2: 1, sqrt(3)/2 + I/2: 1}")
  expect_equal(mi_fmt(roots(x^5 + 1, x)), "{-1: 1, -sqrt(5)/4 + 1/4 - I*sqrt(sqrt(5)/8 + 5/8): 1, -sqrt(5)/4 + 1/4 + I*sqrt(sqrt(5)/8 + 5/8): 1, 1/4 + sqrt(5)/4 - I*sqrt(5/8 - sqrt(5)/8): 1, 1/4 + sqrt(5)/4 + I*sqrt(5/8 - sqrt(5)/8): 1}")
  expect_equal(mi_fmt(roots(x^3 + x + 1, x)), "{-(27/2 + 3*sqrt(93)/2)^(1/3)/3 + (27/2 + 3*sqrt(93)/2)^(-1/3): 1, -(-1/2 + sqrt(3)*I/2)*(27/2 + 3*sqrt(93)/2)^(1/3)/3 + 1/((-1/2 + sqrt(3)*I/2)*(27/2 + 3*sqrt(93)/2)^(1/3)): 1, 1/((-1/2 - sqrt(3)*I/2)*(27/2 + 3*sqrt(93)/2)^(1/3)) - (-1/2 - sqrt(3)*I/2)*(27/2 + 3*sqrt(93)/2)^(1/3)/3: 1}")
  expect_equal(mi_fmt(roots(x^3 - 3*x + 1, x)), "{-(27/2 + 27*sqrt(3)*I/2)^(1/3)/3 - 3/(27/2 + 27*sqrt(3)*I/2)^(1/3): 1, -(-1/2 + sqrt(3)*I/2)*(27/2 + 27*sqrt(3)*I/2)^(1/3)/3 - 3/((-1/2 + sqrt(3)*I/2)*(27/2 + 27*sqrt(3)*I/2)^(1/3)): 1, -3/((-1/2 - sqrt(3)*I/2)*(27/2 + 27*sqrt(3)*I/2)^(1/3)) - (-1/2 - sqrt(3)*I/2)*(27/2 + 27*sqrt(3)*I/2)^(1/3)/3: 1}")
  expect_equal(mi_fmt(roots(x^4 + x + 1, x)), "{sqrt(-2*(1/16 + sqrt(687)*I/144)^(1/3) + 2/sqrt(2/(3*(1/16 + sqrt(687)*I/144)^(1/3)) + 2*(1/16 + sqrt(687)*I/144)^(1/3)) - 2/(3*(1/16 + sqrt(687)*I/144)^(1/3)))/2 - sqrt(2/(3*(1/16 + sqrt(687)*I/144)^(1/3)) + 2*(1/16 + sqrt(687)*I/144)^(1/3))/2: 1, -sqrt(2/(3*(1/16 + sqrt(687)*I/144)^(1/3)) + 2*(1/16 + sqrt(687)*I/144)^(1/3))/2 - sqrt(-2*(1/16 + sqrt(687)*I/144)^(1/3) + 2/sqrt(2/(3*(1/16 + sqrt(687)*I/144)^(1/3)) + 2*(1/16 + sqrt(687)*I/144)^(1/3)) - 2/(3*(1/16 + sqrt(687)*I/144)^(1/3)))/2: 1, sqrt(-2*(1/16 + sqrt(687)*I/144)^(1/3) - 2/sqrt(2/(3*(1/16 + sqrt(687)*I/144)^(1/3)) + 2*(1/16 + sqrt(687)*I/144)^(1/3)) - 2/(3*(1/16 + sqrt(687)*I/144)^(1/3)))/2 + sqrt(2/(3*(1/16 + sqrt(687)*I/144)^(1/3)) + 2*(1/16 + sqrt(687)*I/144)^(1/3))/2: 1, sqrt(2/(3*(1/16 + sqrt(687)*I/144)^(1/3)) + 2*(1/16 + sqrt(687)*I/144)^(1/3))/2 - sqrt(-2*(1/16 + sqrt(687)*I/144)^(1/3) - 2/sqrt(2/(3*(1/16 + sqrt(687)*I/144)^(1/3)) + 2*(1/16 + sqrt(687)*I/144)^(1/3)) - 2/(3*(1/16 + sqrt(687)*I/144)^(1/3)))/2: 1}")
  expect_equal(mi_fmt(roots(x^2 - 2, x)), "{-sqrt(2): 1, sqrt(2): 1}")
  expect_equal(mi_fmt(roots(2*x^2 - 3, x)), "{-sqrt(6)/2: 1, sqrt(6)/2: 1}")
  expect_equal(mi_fmt(roots(x^2 + x + 1, x)), "{-1/2 - sqrt(3)*I/2: 1, -1/2 + sqrt(3)*I/2: 1}")
  expect_equal(mi_fmt(roots(x^2 + a, x)), "{-sqrt(-a): 1, sqrt(-a): 1}")
  expect_equal(mi_fmt(roots(a*x^2 + b*x + c, x)), "{-b/(2*a) - sqrt(-4*a*c + b^2)/(2*a): 1, -b/(2*a) + sqrt(-4*a*c + b^2)/(2*a): 1}")
  expect_equal(mi_fmt(roots(4*(k^2 + 1)*x^2 + 1, x)), "{-I/(2*sqrt(k^2 + 1)): 1, I/(2*sqrt(k^2 + 1)): 1}")
  expect_equal(mi_fmt(roots(x^2 - 2*a*x + a^2 - b, x)), "{a - sqrt(b): 1, a + sqrt(b): 1}")
  expect_equal(mi_fmt(roots(x^3 - a, x)), "{a^(1/3): 1, -a^(1/3)/2 - sqrt(3)*I*a^(1/3)/2: 1, -a^(1/3)/2 + sqrt(3)*I*a^(1/3)/2: 1}")
  expect_equal(mi_fmt(roots(x^8 - 1, x)), "{-1: 1, 1: 1, -sqrt(2)/2 - sqrt(2)*I/2: 1, -sqrt(2)/2 + sqrt(2)*I/2: 1, -I: 1, I: 1, sqrt(2)/2 - sqrt(2)*I/2: 1, sqrt(2)/2 + sqrt(2)*I/2: 1}")
  expect_equal(mi_fmt(roots(x^4 + x^3 + x^2 + x + 1, x)), "{-sqrt(5)/4 - 1/4 - I*sqrt(5/8 - sqrt(5)/8): 1, -sqrt(5)/4 - 1/4 + I*sqrt(5/8 - sqrt(5)/8): 1, -1/4 + sqrt(5)/4 - I*sqrt(sqrt(5)/8 + 5/8): 1, -1/4 + sqrt(5)/4 + I*sqrt(sqrt(5)/8 + 5/8): 1}")
  expect_equal(mi_fmt(roots(x^6 - 1, x)), "{-1: 1, 1: 1, -1/2 - sqrt(3)*I/2: 1, -1/2 + sqrt(3)*I/2: 1, 1/2 - sqrt(3)*I/2: 1, 1/2 + sqrt(3)*I/2: 1}")
  expect_equal(mi_fmt(roots(x^3 - 7*x^2 + 14*x - 8, x)), "{4: 1, 2: 1, 1: 1}")
  expect_equal(mi_fmt(roots(x^4 - 10*x^2 + 1, x)), "{-sqrt(5 - 2*sqrt(6)): 1, sqrt(5 - 2*sqrt(6)): 1, -sqrt(2*sqrt(6) + 5): 1, sqrt(2*sqrt(6) + 5): 1}")
  expect_equal(mi_fmt(roots(x^2 - sqrt(Integer(2))*x + 1, x)), "{sqrt(2)/2 - sqrt(2)*I/2: 1, sqrt(2)/2 + sqrt(2)*I/2: 1}")
  expect_equal(mi_fmt(roots(x^3 + 2*x^2 + 3*x + 4, x)), "{-(35 + 15*sqrt(6))^(1/3)/3 - 2/3 + 5/(3*(35 + 15*sqrt(6))^(1/3)): 1, -2/3 - (-1/2 + sqrt(3)*I/2)*(35 + 15*sqrt(6))^(1/3)/3 + 5/(3*(-1/2 + sqrt(3)*I/2)*(35 + 15*sqrt(6))^(1/3)): 1, -2/3 + 5/(3*(-1/2 - sqrt(3)*I/2)*(35 + 15*sqrt(6))^(1/3)) - (-1/2 - sqrt(3)*I/2)*(35 + 15*sqrt(6))^(1/3)/3: 1}")
  expect_equal(mi_fmt(roots(x^4 + 4*x^3 + 6*x^2 + 4*x + 1, x)), "{-1: 4}")
  expect_equal(mi_fmt(roots(x^6 - 2*x^3 + 1, x)), "{1: 2, -1/2 - sqrt(3)*I/2: 2, -1/2 + sqrt(3)*I/2: 2}")
  expect_equal(mi_fmt(roots(x^2*(x + 1), x)), "{-1: 1, 0: 2}")
  expect_equal(mi_fmt(roots(x^4 + 2*x^2 + 1, x)), "{-I: 2, I: 2}")
  expect_equal(mi_fmt(roots(Rational(1, 2)*x^2 - Rational(1, 8), x)), "{-1/2: 1, 1/2: 1}")
  expect_equal(mi_fmt(roots(x^3 - 2, x)), "{2^(1/3): 1, -2^(1/3)/2 - 2^(1/3)*sqrt(3)*I/2: 1, -2^(1/3)/2 + 2^(1/3)*sqrt(3)*I/2: 1}")
  expect_equal(mi_fmt(roots(x^2 + 2*sym_I*x - 1, x)), "{-I: 2}")
  expect_equal(mi_fmt(roots(x^4 - 4*x^2 + 1, x)), "{-sqrt(2 - sqrt(3)): 1, sqrt(2 - sqrt(3)): 1, -sqrt(sqrt(3) + 2): 1, sqrt(sqrt(3) + 2): 1}")
  expect_equal(mi_fmt(roots(x^3 - 3*x^2 + 3*x - 1 - a, x)), "{a^(1/3) + 1: 1, a^(1/3)*(-1/2 + sqrt(3)*I/2) + 1: 1, a^(1/3)*(-1/2 - sqrt(3)*I/2) + 1: 1}")
  expect_equal(mi_fmt(roots(x^2 - 4*x + 1, x, multiple = TRUE)), "[sqrt(3) + 2, 2 - sqrt(3)]")
  expect_equal(mi_fmt(roots(x^3 + x^2 - 2, x, multiple = TRUE)), "[1, -1 + I, -1 - I]")
  expect_equal(mi_fmt(roots(x^5 - x^4 - x + 1, x)), "{-1: 1, 1: 2, -I: 1, I: 1}")
  expect_equal(mi_fmt(roots(x^3 - 3*x + 1, x, trig = TRUE)), "{2*cos(2*pi/9): 1, 2*cos(4*pi/9): 1, -2*cos(pi/9): 1}")
})
